import{_ as i,o as a,c as t,ae as o}from"./chunks/framework.CK6jtcgr.js";const h=JSON.parse('{"title":"Agent Plane and Operator Workflows","description":"","frontmatter":{},"headers":[],"relativePath":"guide/agent-plane-and-operator-workflows.md","filePath":"guide/agent-plane-and-operator-workflows.md"}'),l={name:"guide/agent-plane-and-operator-workflows.md"};function n(r,e,s,d,p,u){return a(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="agent-plane-and-operator-workflows" tabindex="-1">Agent Plane and Operator Workflows <a class="header-anchor" href="#agent-plane-and-operator-workflows" aria-label="Permalink to &quot;Agent Plane and Operator Workflows&quot;">​</a></h1><p>This page is the public manual entry point for the operator workflow layer inside SocioProphet.</p><p>The Agent Plane explains how work moves from intent to bounded capability, from bounded capability to controlled execution, and from controlled execution to evidence, review, promotion, or reversal.</p><h2 id="_1-purpose" tabindex="-1">1. Purpose <a class="header-anchor" href="#_1-purpose" aria-label="Permalink to &quot;1. Purpose&quot;">​</a></h2><p>The Agent Plane exists so institutions and operators can understand:</p><ul><li>who is acting</li><li>what capability is in play</li><li>what state the workflow occupies</li><li>what evidence the workflow emits</li><li>what review or reversal path exists</li></ul><p>This is the operational layer that keeps the broader system governable.</p><h2 id="_2-core-model" tabindex="-1">2. Core model <a class="header-anchor" href="#_2-core-model" aria-label="Permalink to &quot;2. Core model&quot;">​</a></h2><p>The public model is straightforward:</p><ol><li>intent enters the system</li><li>capability is routed under policy</li><li>execution occurs inside an explicit boundary</li><li>evidence is emitted</li><li>the result is reviewed, promoted, or reversed</li></ol><p>This is not a hidden automation loop. It is an explicit operational model.</p><h2 id="_3-roles" tabindex="-1">3. Roles <a class="header-anchor" href="#_3-roles" aria-label="Permalink to &quot;3. Roles&quot;">​</a></h2><p>The public-facing role model includes:</p><ul><li>requester</li><li>reviewer</li><li>executor</li><li>auditor</li><li>safeguarding or governance authority where needed</li></ul><p>The goal is role separation, not ambient authority.</p><h2 id="_4-workflow-states" tabindex="-1">4. Workflow states <a class="header-anchor" href="#_4-workflow-states" aria-label="Permalink to &quot;4. Workflow states&quot;">​</a></h2><p>A workflow may move through states such as:</p><ul><li>proposed</li><li>approved</li><li>executing</li><li>degraded</li><li>paused</li><li>completed</li><li>reviewed</li><li>reversed</li><li>remediated</li></ul><p>These states matter because the system is built to keep transitions attributable and bounded.</p><h2 id="_5-capability-routing" tabindex="-1">5. Capability routing <a class="header-anchor" href="#_5-capability-routing" aria-label="Permalink to &quot;5. Capability routing&quot;">​</a></h2><p>The Agent Plane does not treat every connected tool as globally available.</p><p>Capability routing is bounded by:</p><ul><li>provider eligibility</li><li>operator role</li><li>scope</li><li>policy</li><li>safeguarding constraints</li><li>review requirements</li></ul><p>Relevant references:</p><ul><li><a href="/documentation/guide/auth-and-connections">Auth and Connections</a></li><li><a href="/documentation/guide/provider-capability-routing">Provider Capability Routing</a></li><li><a href="/documentation/guide/provider-safety-and-capability-eligibility">Provider Safety and Capability Eligibility</a></li><li><a href="/documentation/guide/auth-recovery-and-connection-health">Auth Recovery and Connection Health</a></li></ul><h2 id="_6-relationship-to-governed-ai-and-cybernetics" tabindex="-1">6. Relationship to governed AI and cybernetics <a class="header-anchor" href="#_6-relationship-to-governed-ai-and-cybernetics" aria-label="Permalink to &quot;6. Relationship to governed AI and cybernetics&quot;">​</a></h2><p>The Agent Plane sits inside the broader governed operational model.</p><p>That means it inherits:</p><ul><li>bounded execution</li><li>reviewable transitions</li><li>promotion and reversal logic</li><li>deterministic safety posture</li><li>public versus restricted boundary management</li></ul><p>Relevant references:</p><ul><li><a href="/documentation/guide/governed-ai-and-cybernetics">Governed AI and Cybernetics</a></li><li><a href="/documentation/guide/deterministic-ai-and-mathematical-safety">Deterministic AI and Mathematical Safety</a></li><li><a href="/documentation/guide/provenance-promotion-and-reversibility">Provenance, Promotion, and Reversibility</a></li></ul><h2 id="_7-relationship-to-entity-analytics" tabindex="-1">7. Relationship to Entity Analytics <a class="header-anchor" href="#_7-relationship-to-entity-analytics" aria-label="Permalink to &quot;7. Relationship to Entity Analytics&quot;">​</a></h2><p>The Agent Plane depends on governed identity, scope, and event structure.</p><p>It relies on Entity Analytics for:</p><ul><li>typed events</li><li>scope discipline</li><li>identity-prime structure</li><li>merge control</li><li>evidence trails</li><li>proof artifacts</li></ul><p>Relevant references:</p><ul><li><a href="/documentation/guide/entity-analytics-reference">Entity Analytics Reference</a></li><li><a href="/documentation/guide/identity-prime-and-event-ir">Identity Prime and Event-IR</a></li><li><a href="/documentation/guide/worked-example-michael-cross-context">Worked Example: Michael Cross-Context</a></li></ul><h2 id="_8-relationship-to-organizations" tabindex="-1">8. Relationship to organizations <a class="header-anchor" href="#_8-relationship-to-organizations" aria-label="Permalink to &quot;8. Relationship to organizations&quot;">​</a></h2><p>The Organizations surface is the institutional umbrella for deployment.</p><p>The Agent Plane is one governed subsystem inside that umbrella.</p><p>Relevant references:</p><ul><li><a href="/documentation/guide/organizations-governance-and-institutional-safety">Organizations Governance and Institutional Safety</a></li><li><a href="/documentation/guide/authorized-cyberdefense-and-simulation">Authorized Cyberdefense and Simulation</a></li></ul><h2 id="_9-public-safe-boundary" tabindex="-1">9. Public-safe boundary <a class="header-anchor" href="#_9-public-safe-boundary" aria-label="Permalink to &quot;9. Public-safe boundary&quot;">​</a></h2><p>This page explains:</p><ul><li>role model</li><li>workflow states</li><li>capability routing</li><li>governance relationship</li><li>evidence relationship</li><li>public-safe control logic</li></ul><p>It does not publish:</p><ul><li>sensitive operator kits</li><li>restricted tactical playbooks</li><li>exploit or persistence workflows</li><li>private thresholds</li><li>misuse-enabling automation details</li></ul><p>That restriction is part of the safety model.</p><h2 id="_10-why-this-matters" tabindex="-1">10. Why this matters <a class="header-anchor" href="#_10-why-this-matters" aria-label="Permalink to &quot;10. Why this matters&quot;">​</a></h2><p>Without an explicit Agent Plane, institutions get:</p><ul><li>disconnected tools</li><li>hidden authority chains</li><li>weak accountability</li><li>unclear workflow state</li><li>ambiguous review boundaries</li></ul><p>The Agent Plane gives the system a real operational layer instead of a pile of loosely connected features.</p><h2 id="_11-use-this-page" tabindex="-1">11. Use this page <a class="header-anchor" href="#_11-use-this-page" aria-label="Permalink to &quot;11. Use this page&quot;">​</a></h2><p>Use this page when the question is:</p><ul><li>How does work move through the system operationally?</li><li>How do roles, capability routing, and workflow state fit together?</li><li>How does the Agent Plane connect to governance, analytics, and institutional deployment?</li><li>What does the public layer explain, and what remains restricted?</li></ul>',55)])])}const m=i(l,[["render",n]]);export{h as __pageData,m as default};
